<?php
declare(strict_types=1);
ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function tt_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
function tt_audit(PDO $db,int $uid,string $action,int $id,int $school):void{$q=$db->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,'class_timetable_entry',?,?)");$q->execute([$uid,$action,$id,json_encode(['school_id'=>$school],JSON_THROW_ON_ERROR)]);}
if(!signed_in())tt_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))tt_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$db=db();$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];$leadership=['director','sub_director','headteacher','head_academic'];$editable=in_array($role,$leadership,true);
function tt_rows(PDO $db,int $school,string $where,array $params):array{$sql="SELECT t.id,t.class_id,c.name class_name,t.stream_id,st.name stream_name,t.subject_id,s.name subject_name,t.teacher_id,u.name teacher_name,t.day_of_week,t.starts_at,t.ends_at,t.room,t.status FROM class_timetable_entries t JOIN school_classes c ON c.id=t.class_id AND c.school_id=t.school_id JOIN school_class_subjects s ON s.id=t.subject_id AND s.class_id=t.class_id JOIN users u ON u.id=t.teacher_id LEFT JOIN school_streams st ON st.id=t.stream_id WHERE t.school_id=? $where ORDER BY t.day_of_week,t.starts_at,c.name";$q=$db->prepare($sql);$q->execute([$school,...$params]);return$q->fetchAll();}
if($role==='pupil'||$role==='parent'){$pupilId=0;if($role==='pupil'){$q=$db->prepare("SELECT p.id,p.school_id,p.class_level,p.stream FROM pupil_accounts a JOIN pupils p ON p.id=a.pupil_id AND p.school_id=a.school_id WHERE a.user_id=? AND a.active=1 AND p.status='active' LIMIT 1");$q->execute([$uid]);$child=$q->fetch();}else{$pupilId=filter_var($_GET['pupil_id']??null,FILTER_VALIDATE_INT)?:0;$q=$db->prepare("SELECT p.id,p.school_id,p.class_level,p.stream FROM pupil_guardians g JOIN pupils p ON p.id=g.pupil_id AND p.school_id=g.school_id WHERE g.guardian_user_id=? AND p.id=? AND p.status='active' LIMIT 1");$q->execute([$uid,$pupilId]);$child=$q->fetch();}if(!$child)tt_json(404,['ok'=>false,'message'=>'No linked active pupil record was found.']);$streamId=null;if($child['stream']!==null){$q=$db->prepare('SELECT id FROM school_streams WHERE class_id=(SELECT id FROM school_classes WHERE school_id=? AND name=?) AND name=?');$q->execute([$child['school_id'],$child['class_level'],$child['stream']]);$streamId=$q->fetchColumn()?:null;}$entries=tt_rows($db,(int)$child['school_id'],"AND t.status='published' AND c.name=? AND (t.stream_id IS NULL OR t.stream_id=?)",[$child['class_level'],$streamId]);tt_json(200,['ok'=>true,'data'=>['entries'=>$entries,'class_name'=>$child['class_level']]]);}
if(!$editable&&$role!=='teacher')tt_json(403,['ok'=>false,'message'=>'Your role cannot view a timetable.']);$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);if(!$school)tt_json(422,['ok'=>false,'message'=>'Choose a school.']);$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())tt_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
if($_SERVER['REQUEST_METHOD']==='GET'){$view=(string)($_GET['view']??'list');if($view==='catalog'){if(!$editable)tt_json(403,['ok'=>false,'message'=>'Only school leadership can manage the timetable.']);$q=$db->prepare('SELECT id,name FROM school_classes WHERE school_id=? ORDER BY name');$q->execute([$school]);$classes=$q->fetchAll();$q=$db->prepare('SELECT s.id,s.class_id,s.name FROM school_class_subjects s JOIN school_classes c ON c.id=s.class_id WHERE c.school_id=? ORDER BY c.name,s.name');$q->execute([$school]);$subjects=$q->fetchAll();$q=$db->prepare('SELECT st.id,st.class_id,st.name FROM school_streams st JOIN school_classes c ON c.id=st.class_id WHERE c.school_id=? ORDER BY c.name,st.name');$q->execute([$school]);$streams=$q->fetchAll();$q=$db->prepare("SELECT DISTINCT u.id,u.name,a.class_level,a.subject FROM teacher_assignments a JOIN users u ON u.id=a.user_id JOIN school_memberships m ON m.user_id=u.id AND m.school_id=a.school_id WHERE a.school_id=? AND a.active=1 AND u.status='active' AND u.role='teacher' ORDER BY u.name,a.class_level,a.subject");$q->execute([$school]);tt_json(200,['ok'=>true,'data'=>['classes'=>$classes,'subjects'=>$subjects,'streams'=>$streams,'teacher_assignments'=>$q->fetchAll()]]);}$where=$editable?'':'AND t.teacher_id=? AND t.status=\'published\'';$params=$editable?[]:[$uid];$entries=tt_rows($db,(int)$school,$where,$params);tt_json(200,['ok'=>true,'data'=>['entries'=>$entries,'can_edit'=>$editable]]);}
if($_SERVER['REQUEST_METHOD']!=='POST'||!$editable)tt_json(403,['ok'=>false,'message'=>'Only school leadership can change the timetable.']);verify_csrf();$action=(string)($_POST['action']??'');
if($action==='save_entry'){$classId=filter_var($_POST['class_id']??null,FILTER_VALIDATE_INT);$subjectId=filter_var($_POST['subject_id']??null,FILTER_VALIDATE_INT);$teacherId=filter_var($_POST['teacher_id']??null,FILTER_VALIDATE_INT);$streamId=filter_var($_POST['stream_id']??null,FILTER_VALIDATE_INT)?:null;$day=filter_var($_POST['day_of_week']??null,FILTER_VALIDATE_INT);$start=(string)($_POST['starts_at']??'');$end=(string)($_POST['ends_at']??'');$room=trim((string)($_POST['room']??''));$status=(string)($_POST['status']??'draft');if(!$classId||!$subjectId||!$teacherId||$day<1||$day>7||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$start)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$end)||$start>=$end||mb_strlen($room)>80||!in_array($status,['draft','published'],true))tt_json(422,['ok'=>false,'message'=>'Enter a valid class, subject, teacher, weekday, time range, and status.']);$q=$db->prepare('SELECT c.name class_name,s.name subject_name FROM school_classes c JOIN school_class_subjects s ON s.class_id=c.id WHERE c.id=? AND c.school_id=? AND s.id=?');$q->execute([$classId,$school,$subjectId]);$pair=$q->fetch();if(!$pair)tt_json(422,['ok'=>false,'message'=>'The subject does not belong to this school class.']);if($streamId){$q=$db->prepare('SELECT 1 FROM school_streams WHERE id=? AND class_id=?');$q->execute([$streamId,$classId]);if(!$q->fetchColumn())tt_json(422,['ok'=>false,'message'=>'The stream does not belong to this class.']);}$q=$db->prepare("SELECT 1 FROM teacher_assignments a JOIN users u ON u.id=a.user_id WHERE a.user_id=? AND a.school_id=? AND a.active=1 AND a.class_level=? AND a.subject=? AND u.status='active' AND u.role='teacher'");$q->execute([$teacherId,$school,$pair['class_name'],$pair['subject_name']]);if(!$q->fetchColumn())tt_json(422,['ok'=>false,'message'=>'Choose a teacher assigned to this class and subject.']);$db->beginTransaction();try{$q=$db->prepare('SELECT id FROM school_classes WHERE id=? AND school_id=? FOR UPDATE');$q->execute([$classId,$school]);if(!$q->fetchColumn())throw new DomainException('Class is unavailable.');$q=$db->prepare('SELECT id FROM users WHERE id=? AND status=\'active\' FOR UPDATE');$q->execute([$teacherId]);if(!$q->fetchColumn())throw new DomainException('Teacher is unavailable.');$q=$db->prepare("SELECT id FROM class_timetable_entries WHERE school_id=? AND day_of_week=? AND status IN ('draft','published') AND starts_at<? AND ends_at>? AND ((class_id=? AND (stream_id IS NULL OR ? IS NULL OR stream_id=?)) OR teacher_id=?) LIMIT 1");$q->execute([$school,$day,$end,$start,$classId,$streamId,$streamId,$teacherId]);if($q->fetchColumn())throw new DomainException('This time overlaps another entry for the same class/stream or teacher.');$q=$db->prepare('INSERT INTO class_timetable_entries(school_id,class_id,stream_id,subject_id,teacher_id,day_of_week,starts_at,ends_at,room,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$school,$classId,$streamId,$subjectId,$teacherId,$day,$start,$end,$room?:null,$status,$uid]);$id=(int)$db->lastInsertId();tt_audit($db,$uid,'create',$id,(int)$school);$db->commit();tt_json(200,['ok'=>true,'message'=>$status==='published'?'Timetable entry published.':'Timetable draft saved.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();tt_json($e instanceof DomainException?422:500,['ok'=>false,'message'=>$e instanceof DomainException?$e->getMessage():'Timetable entry could not be saved.']);}}
if(in_array($action,['publish_entry','archive_entry'],true)){$id=filter_var($_POST['entry_id']??null,FILTER_VALIDATE_INT);if(!$id)tt_json(422,['ok'=>false,'message'=>'Choose a timetable entry.']);$next=$action==='publish_entry'?'published':'archived';$q=$db->prepare('SELECT id FROM class_timetable_entries WHERE id=? AND school_id=?');$q->execute([$id,$school]);if(!$q->fetchColumn())tt_json(404,['ok'=>false,'message'=>'Timetable entry not found.']);$db->prepare('UPDATE class_timetable_entries SET status=? WHERE id=? AND school_id=?')->execute([$next,$id,$school]);tt_audit($db,$uid,$action,$id,(int)$school);tt_json(200,['ok'=>true,'message'=>$next==='published'?'Timetable entry published.':'Timetable entry archived.']);}
tt_json(422,['ok'=>false,'message'=>'Unknown timetable action.']);
